// Exercise the dimension counts passed to target kernel launches. The first
// count is also passed directly to __tgt_target_kernel; the remaining counts
// are available through the three-element arrays in the kernel arguments.

// A single dimension with dims must retain the ordinary scalar behavior.
void one_dimensional_modifiers() {
#pragma omp target teams num_teams(dims(1): 3) thread_limit(dims(1): 16)
  {}
}

void target_without_clauses() {
#pragma omp target
  {}
}

// Target teams can specify independent numbers of teams and threads.
void target_teams_num_teams_only() {
#pragma omp target teams num_teams(dims(3): 2, 3, 4)
  {}
}

void target_teams_num_teams_dynamic(int teams_x, int teams_y) {
#pragma omp target teams num_teams(dims(2): teams_x, teams_y)
  {}
}

void target_teams_thread_limit_only() {
#pragma omp target teams thread_limit(dims(3): 32, 8, 4)
  {}
}

void target_teams_limits() {
#pragma omp target teams num_teams(dims(2): 3, 2) thread_limit(dims(2): 16, 8)
  {}
}

void target_thread_limit_only() {
#pragma omp target thread_limit(dims(2): 32, 8)
  {}
}

void target_nested_parallel(int threads_x, int threads_y) {
#pragma omp target thread_limit(dims(2): 32, 8)
#pragma omp parallel num_threads(dims(2): threads_x, threads_y)
  {}
}

void target_nested_teams_parallel() {
#pragma omp target
#pragma omp teams thread_limit(dims(2): 32, 8)
#pragma omp parallel num_threads(dims(2): 16, 4)
  {}
}

void nested_teams_limit_overrides_target_limit() {
#pragma omp target thread_limit(dims(2): 64, 16)
#pragma omp teams thread_limit(dims(2): 32, 8)
  {}
}

void target_teams_distribute() {
#pragma omp target teams distribute thread_limit(dims(2): 32, 8)
  for (int i = 0; i < 4; ++i) {}
}

void target_teams_distribute_parallel_for() {
#pragma omp target teams distribute parallel for thread_limit(dims(2): 32, 8) num_threads(dims(2): 16, 4)
  for (int i = 0; i < 4; ++i) {}
}

void target_teams_distribute_parallel_for_simd() {
#pragma omp target teams distribute parallel for simd thread_limit(dims(2): 32, 8) num_threads(dims(2): 16, 4)
  for (int i = 0; i < 4; ++i) {}
}

void target_teams_distribute_simd() {
#pragma omp target teams distribute simd num_teams(dims(2): 3, 2) thread_limit(dims(2): 32, 8)
  for (int i = 0; i < 4; ++i) {}
}

void target_teams_loop() {
#pragma omp target teams loop num_teams(dims(2): 3, 2) thread_limit(dims(2): 32, 8)
  for (int i = 0; i < 4; ++i) {}
}

// Combined parallel directives pass num_threads values to the launch.
void target_parallel_thread_limit_only() {
#pragma omp target parallel thread_limit(dims(2): 32, 8)
  {}
}

void target_parallel_threads_dynamic(int threads_x, int threads_y) {
#pragma omp target parallel num_threads(dims(2): threads_x, threads_y)
  {}
}

void target_parallel_one_thread_dimension() {
#pragma omp target parallel num_threads(dims(1): 16)
  {}
}

void target_parallel_threads() {
#pragma omp target parallel num_threads(dims(3): 8, 4, 2)
  {}
}

void target_parallel_for() {
#pragma omp target parallel for num_threads(dims(2): 16, 4)
  for (int i = 0; i < 4; ++i) {}
}

void target_parallel_for_simd() {
#pragma omp target parallel for simd num_threads(dims(2): 16, 4)
  for (int i = 0; i < 4; ++i) {}
}

void target_parallel_loop() {
#pragma omp target parallel loop num_threads(dims(2): 16, 4)
  for (int i = 0; i < 4; ++i) {}
}

// Both clauses constrain each dimension separately.
void target_parallel_dynamic(int limit_x, int limit_y, int threads_x,
                             int threads_y) {
#pragma omp target parallel thread_limit(dims(2): limit_x, limit_y) num_threads(dims(2): threads_x, threads_y)
  {}
}

void target_parallel_constant_limit(int threads_x, int threads_y) {
#pragma omp target parallel thread_limit(dims(2): 32, 8) num_threads(dims(2): threads_x, threads_y)
  {}
}

void target_parallel_dynamic_limit(int limit_x, int limit_y) {
#pragma omp target parallel thread_limit(dims(2): limit_x, limit_y) num_threads(dims(2): 16, 4)
  {}
}

void target_parallel_minimum() {
#pragma omp target parallel thread_limit(dims(2): 32, 8) num_threads(dims(2): 16, 16)
  {}
}

void target_parallel_three_dimensions() {
#pragma omp target parallel thread_limit(dims(3): 32, 8, 4) num_threads(dims(3): 16, 16, 2)
  {}
}

void target_parallel_all_ones() {
#pragma omp target parallel num_threads(dims(2): 1, 1)
  {}
}

void nested_target_teams_parallel() {
#pragma omp target teams thread_limit(dims(2): 32, 8)
#pragma omp parallel num_threads(dims(2): 16, 4)
  {}
}

void nested_target_teams_distribute_parallel_for() {
#pragma omp target teams thread_limit(dims(2): 32, 8)
#pragma omp distribute parallel for num_threads(dims(2): 16, 4)
  for (int i = 0; i < 4; ++i) {}
}

// A dynamic condition selects one thread in each dimension when false.
void conditional_target_parallel(int cond, int threads_x, int threads_y) {
#pragma omp target parallel if(parallel: cond) num_threads(dims(2): threads_x, threads_y)
  {}
}

void conditional_target_parallel_with_limit(int cond) {
#pragma omp target parallel if(parallel: cond) thread_limit(dims(2): 32, 8) num_threads(dims(2): 16, 4)
  {}
}

void disabled_target_parallel() {
#pragma omp target parallel if(parallel: 0) num_threads(dims(2): 16, 4)
  {}
}

void enabled_target_parallel() {
#pragma omp target parallel if(parallel: 1) num_threads(dims(2): 16, 4)
  {}
}

// A longer thread_limit leaves the extra launch dimensions at one thread.

void extra_limit_dimensions_1() {
#pragma omp target parallel thread_limit(dims(2): 32, 8) num_threads(16)
  {}
}

void extra_limit_dimensions_2() {
#pragma omp target parallel thread_limit(dims(2): 32, 8) num_threads(dims(1): 16)
  {}
}

void extra_limit_dimensions_3() {
#pragma omp target parallel thread_limit(dims(3): 32, 8, 4) num_threads(16)
  {}
}

void extra_limit_dimensions_4() {
#pragma omp target parallel thread_limit(dims(3): 32, 8, 4) num_threads(dims(1): 16)
  {}
}

void extra_limit_dimensions_5() {
#pragma omp target parallel thread_limit(dims(3): 32, 8, 4) num_threads(dims(2): 16, 4)
  {}
}

